-- ForgeFlow initial schema.
-- IDs use UUIDs because they are exposed in QR links and may be generated by clients.
create extension if not exists pgcrypto;
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
grant usage on schema private to authenticated;

create table public.organizations (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(trim(name)) > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.customers (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete restrict,
  customer_name text not null check (length(trim(customer_name)) > 0),
  primary_address text not null default '',
  default_ship_to_address text not null default '',
  default_bill_to_address text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (organization_id, customer_name),
  unique (id, organization_id)
);

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  organization_id uuid not null references public.organizations(id) on delete restrict,
  customer_id uuid references public.customers(id) on delete restrict,
  display_name text not null check (length(trim(display_name)) > 0),
  role text not null check (role in ('manufacturer', 'customer')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check ((role = 'manufacturer' and customer_id is null) or (role = 'customer' and customer_id is not null))
);

create table public.sales_orders (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete restrict,
  sales_order_number text not null,
  customer_id uuid not null references public.customers(id) on delete restrict,
  customer_name text not null,
  customer_address text not null default '',
  customer_po_number text not null check (length(trim(customer_po_number)) > 0),
  ship_to_address text not null default '',
  bill_to_address text not null default '',
  date_received date not null,
  order_due_date date not null,
  notes text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (organization_id, sales_order_number),
  unique (id, organization_id),
  unique (id, customer_id, organization_id),
  foreign key (customer_id, organization_id) references public.customers(id, organization_id)
);

create table public.sales_order_line_items (
  id uuid primary key default gen_random_uuid(),
  sales_order_id uuid not null references public.sales_orders(id) on delete cascade,
  line_number integer not null check (line_number > 0),
  part_number text,
  description text not null check (length(trim(description)) > 0),
  manufactured_item boolean not null default false,
  pricing_type text not null check (pricing_type in ('per_piece', 'flat_rate')),
  quantity integer not null default 1 check (quantity > 0),
  unit_price numeric(12,2),
  flat_rate_amount numeric(12,2),
  line_total numeric(14,2) generated always as (
    case when pricing_type = 'per_piece' then quantity * coalesce(unit_price, 0) else coalesce(flat_rate_amount, 0) end
  ) stored,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (sales_order_id, line_number),
  unique (id, sales_order_id),
  check (
    (pricing_type = 'per_piece' and unit_price is not null and unit_price >= 0 and flat_rate_amount is null)
    or (pricing_type = 'flat_rate' and flat_rate_amount is not null and flat_rate_amount >= 0 and unit_price is null)
  ),
  check (not manufactured_item or part_number is not null)
);

create table public.work_orders (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete restrict,
  work_order_number text not null,
  sales_order_id uuid not null references public.sales_orders(id) on delete restrict,
  sales_order_line_item_id uuid not null references public.sales_order_line_items(id) on delete restrict,
  part_number text not null check (length(trim(part_number)) > 0),
  quantity_ordered integer not null check (quantity_ordered > 0),
  due_date date not null,
  released_at timestamptz not null default now(),
  completion_date date,
  notes text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (organization_id, work_order_number),
  unique (id, organization_id),
  foreign key (sales_order_id, organization_id) references public.sales_orders(id, organization_id),
  foreign key (sales_order_line_item_id, sales_order_id) references public.sales_order_line_items(id, sales_order_id)
);

create table public.routing_steps (
  id uuid primary key default gen_random_uuid(),
  work_order_id uuid not null references public.work_orders(id) on delete cascade,
  sequence_number integer not null check (sequence_number > 0),
  routing_step_name text not null check (length(trim(routing_step_name)) > 0),
  customer_stage_name text not null default 'In production' check (length(trim(customer_stage_name)) > 0),
  work_instructions text not null default '',
  work_instructions_revision text,
  notes text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (work_order_id, sequence_number)
);

-- A separate safe mapping prevents portal users from querying internal operation names/instructions.
create table public.customer_stage_mappings (
  routing_step_id uuid primary key references public.routing_steps(id) on delete cascade,
  work_order_id uuid not null references public.work_orders(id) on delete cascade,
  sequence_number integer not null,
  customer_stage_name text not null
);

create table public.production_events (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete restrict,
  work_order_id uuid not null,
  routing_step_id uuid not null references public.routing_steps(id) on delete restrict,
  event_type text not null check (event_type in ('release', 'adjustment', 'transfer', 'scrap', 'reversal')),
  quantity integer not null check (quantity > 0),
  from_routing_step_id uuid references public.routing_steps(id) on delete restrict,
  to_routing_step_id uuid references public.routing_steps(id) on delete restrict,
  reversed_event_id uuid unique references public.production_events(id) on delete restrict,
  created_at timestamptz not null default now(),
  foreign key (work_order_id, organization_id) references public.work_orders(id, organization_id),
  check (
    (event_type in ('release', 'adjustment') and from_routing_step_id is null and to_routing_step_id = routing_step_id and reversed_event_id is null)
    or (event_type = 'transfer' and from_routing_step_id = routing_step_id and reversed_event_id is null)
    or (event_type = 'scrap' and from_routing_step_id is null and to_routing_step_id is null and reversed_event_id is null)
    or (event_type = 'reversal' and reversed_event_id is not null)
  )
);

create table public.customer_messages (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete restrict,
  customer_id uuid not null references public.customers(id) on delete restrict,
  sales_order_id uuid references public.sales_orders(id) on delete restrict,
  sender_type text not null check (sender_type in ('manufacturer', 'customer')),
  message text not null check (
    length(trim(message)) between 1 and 2000
    and message !~* '<[^>]+>'
    and message !~* '(https?://|www[.]|[[:alnum:]][[:alnum:]-]*[.][[:alpha:]]{2,}([/?:#]|[[:space:]]|$))'
  ),
  created_by uuid references auth.users(id) on delete set null default auth.uid(),
  created_at timestamptz not null default now(),
  read_at timestamptz,
  foreign key (customer_id, organization_id) references public.customers(id, organization_id),
  foreign key (sales_order_id, customer_id, organization_id) references public.sales_orders(id, customer_id, organization_id)
);

create table public.invoices (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete restrict,
  customer_id uuid not null references public.customers(id) on delete restrict,
  sales_order_id uuid references public.sales_orders(id) on delete restrict,
  invoice_number text not null,
  invoice_date date not null,
  amount numeric(14,2) check (amount is null or amount >= 0),
  file_path text not null unique check (lower(file_path) like '%.pdf'),
  uploaded_by uuid references auth.users(id) on delete set null default auth.uid(),
  uploaded_at timestamptz not null default now(),
  foreign key (customer_id, organization_id) references public.customers(id, organization_id),
  foreign key (sales_order_id, customer_id, organization_id) references public.sales_orders(id, customer_id, organization_id),
  unique (organization_id, invoice_number)
);

-- Every foreign key / policy lookup used by the application is indexed.
create index profiles_organization_id_idx on public.profiles(organization_id);
create index profiles_customer_id_idx on public.profiles(customer_id) where customer_id is not null;
create index customers_organization_id_idx on public.customers(organization_id);
create index sales_orders_customer_due_idx on public.sales_orders(customer_id, order_due_date);
create index sales_orders_organization_due_idx on public.sales_orders(organization_id, order_due_date);
create index sales_order_line_items_sales_order_id_idx on public.sales_order_line_items(sales_order_id, sort_order);
create index work_orders_sales_order_id_idx on public.work_orders(sales_order_id);
create index work_orders_line_item_id_idx on public.work_orders(sales_order_line_item_id);
create index work_orders_organization_id_idx on public.work_orders(organization_id);
create index work_orders_organization_due_idx on public.work_orders(organization_id, due_date) where completion_date is null;
create index routing_steps_work_order_id_idx on public.routing_steps(work_order_id, sequence_number);
create index customer_stage_mappings_work_order_id_idx on public.customer_stage_mappings(work_order_id, sequence_number);
create index production_events_work_order_created_idx on public.production_events(work_order_id, created_at);
create index production_events_organization_id_idx on public.production_events(organization_id);
create index production_events_routing_step_idx on public.production_events(routing_step_id, created_at);
create index production_events_from_step_idx on public.production_events(from_routing_step_id) where from_routing_step_id is not null;
create index production_events_to_step_idx on public.production_events(to_routing_step_id) where to_routing_step_id is not null;
create unique index production_events_one_release_per_work_order_idx on public.production_events(work_order_id) where event_type = 'release';
create index customer_messages_customer_created_idx on public.customer_messages(customer_id, created_at);
create index customer_messages_organization_id_idx on public.customer_messages(organization_id);
create index customer_messages_sales_order_created_idx on public.customer_messages(sales_order_id, created_at) where sales_order_id is not null;
create index customer_messages_created_by_idx on public.customer_messages(created_by) where created_by is not null;
create index invoices_customer_date_idx on public.invoices(customer_id, invoice_date desc);
create index invoices_organization_id_idx on public.invoices(organization_id);
create index invoices_sales_order_id_idx on public.invoices(sales_order_id) where sales_order_id is not null;
create index invoices_uploaded_by_idx on public.invoices(uploaded_by) where uploaded_by is not null;

create or replace function private.set_updated_at()
returns trigger language plpgsql set search_path = '' as $$
begin new.updated_at = now(); return new; end;
$$;

create trigger organizations_updated_at before update on public.organizations for each row execute function private.set_updated_at();
create trigger customers_updated_at before update on public.customers for each row execute function private.set_updated_at();
create trigger profiles_updated_at before update on public.profiles for each row execute function private.set_updated_at();
create trigger sales_orders_updated_at before update on public.sales_orders for each row execute function private.set_updated_at();
create trigger line_items_updated_at before update on public.sales_order_line_items for each row execute function private.set_updated_at();
create trigger work_orders_updated_at before update on public.work_orders for each row execute function private.set_updated_at();
create trigger routing_steps_updated_at before update on public.routing_steps for each row execute function private.set_updated_at();

create or replace function private.is_manufacturer(p_organization_id uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.profiles
    where id = (select auth.uid()) and organization_id = p_organization_id and role = 'manufacturer'
  );
$$;

create or replace function private.can_access_customer(p_organization_id uuid, p_customer_id uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.profiles
    where id = (select auth.uid()) and organization_id = p_organization_id
      and (role = 'manufacturer' or (role = 'customer' and customer_id = p_customer_id))
  );
$$;

create or replace function private.can_access_work_order(p_work_order_id uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.work_orders wo
    join public.sales_orders so on so.id = wo.sales_order_id
    join public.profiles p on p.id = (select auth.uid())
    where wo.id = p_work_order_id and p.organization_id = wo.organization_id
      and (p.role = 'manufacturer' or (p.role = 'customer' and p.customer_id = so.customer_id))
  );
$$;

revoke all on function private.is_manufacturer(uuid) from public;
revoke all on function private.can_access_customer(uuid, uuid) from public;
revoke all on function private.can_access_work_order(uuid) from public;
grant execute on function private.is_manufacturer(uuid), private.can_access_customer(uuid, uuid), private.can_access_work_order(uuid) to authenticated;

-- Customer portal functions return a deliberately narrow contract. They validate the
-- caller in the private schema and expose no commercial values, notes, routing, or events.
create or replace function private.customer_portal_sales_orders()
returns table (
  id uuid,
  organization_id uuid,
  sales_order_number text,
  customer_id uuid,
  customer_name text,
  customer_po_number text,
  date_received date,
  order_due_date date
)
language sql stable security definer set search_path = '' as $$
  select so.id, so.organization_id, so.sales_order_number, so.customer_id,
    so.customer_name, so.customer_po_number, so.date_received, so.order_due_date
  from public.sales_orders so
  join public.profiles p
    on p.id = (select auth.uid())
    and p.role = 'customer'
    and p.organization_id = so.organization_id
    and p.customer_id = so.customer_id
  order by so.date_received desc;
$$;

create or replace function private.customer_portal_sales_order_lines()
returns table (
  id uuid,
  sales_order_id uuid,
  line_number integer,
  part_number text,
  description text,
  manufactured_item boolean,
  quantity integer,
  sort_order integer
)
language sql stable security definer set search_path = '' as $$
  select li.id, li.sales_order_id, li.line_number, li.part_number, li.description,
    li.manufactured_item, li.quantity, li.sort_order
  from public.sales_order_line_items li
  join public.sales_orders so on so.id = li.sales_order_id
  join public.profiles p
    on p.id = (select auth.uid())
    and p.role = 'customer'
    and p.organization_id = so.organization_id
    and p.customer_id = so.customer_id
  order by li.sort_order, li.line_number;
$$;

create or replace function private.customer_portal_work_orders()
returns table (
  id uuid,
  organization_id uuid,
  sales_order_id uuid,
  sales_order_line_item_id uuid,
  part_number text,
  quantity_ordered integer,
  due_date date,
  completion_date date,
  customer_progress_percent integer,
  customer_stage_name text
)
language sql stable security definer set search_path = '' as $$
  select
    wo.id,
    wo.organization_id,
    wo.sales_order_id,
    wo.sales_order_line_item_id,
    wo.part_number,
    wo.quantity_ordered,
    wo.due_date,
    wo.completion_date,
    case
      when progress.step_count = 0 or wo.quantity_ordered <= 0 then 0
      else least(100, round(
        progress.processed_total::numeric / (wo.quantity_ordered * progress.step_count) * 100
      )::integer)
    end as customer_progress_percent,
    case
      when wo.completion_date is not null then 'Complete'
      when progress.processed_total = 0 then 'Order received'
      else coalesce(current_stage.customer_stage_name, 'In production')
    end as customer_stage_name
  from public.work_orders wo
  join public.sales_orders so on so.id = wo.sales_order_id
  join public.profiles p
    on p.id = (select auth.uid())
    and p.role = 'customer'
    and p.organization_id = wo.organization_id
    and p.customer_id = so.customer_id
  cross join lateral (
    select
      count(*)::integer as step_count,
      coalesce(sum(least(step_activity.processed, wo.quantity_ordered)), 0)::integer as processed_total
    from public.customer_stage_mappings mapping
    cross join lateral (
      select coalesce(sum(pe.quantity) filter (
        where (pe.event_type = 'transfer' and pe.from_routing_step_id = mapping.routing_step_id)
          or (pe.event_type = 'scrap' and pe.routing_step_id = mapping.routing_step_id)
      ), 0)::integer as processed
      from public.production_events pe
      where pe.work_order_id = wo.id
        and pe.event_type <> 'reversal'
        and not exists (
          select 1 from public.production_events reversal where reversal.reversed_event_id = pe.id
        )
    ) step_activity
    where mapping.work_order_id = wo.id
  ) progress
  left join lateral (
    select mapping.customer_stage_name
    from public.customer_stage_mappings mapping
    where mapping.work_order_id = wo.id
      and exists (
        select 1
        from public.production_events pe
        where pe.work_order_id = wo.id
          and pe.event_type <> 'reversal'
          and not exists (
            select 1 from public.production_events reversal where reversal.reversed_event_id = pe.id
          )
          and (
            (pe.event_type in ('release', 'adjustment') and pe.routing_step_id = mapping.routing_step_id)
            or (pe.event_type = 'transfer' and pe.to_routing_step_id = mapping.routing_step_id)
          )
      )
    order by mapping.sequence_number desc
    limit 1
  ) current_stage on true
  order by wo.due_date, wo.id;
$$;

create or replace function public.customer_portal_sales_orders()
returns table (
  id uuid, organization_id uuid, sales_order_number text, customer_id uuid,
  customer_name text, customer_po_number text, date_received date, order_due_date date
)
language sql stable security invoker set search_path = '' as $$
  select * from private.customer_portal_sales_orders();
$$;

create or replace function public.customer_portal_sales_order_lines()
returns table (
  id uuid, sales_order_id uuid, line_number integer, part_number text,
  description text, manufactured_item boolean, quantity integer, sort_order integer
)
language sql stable security invoker set search_path = '' as $$
  select * from private.customer_portal_sales_order_lines();
$$;

create or replace function public.customer_portal_work_orders()
returns table (
  id uuid, organization_id uuid, sales_order_id uuid, sales_order_line_item_id uuid,
  part_number text, quantity_ordered integer, due_date date, completion_date date,
  customer_progress_percent integer, customer_stage_name text
)
language sql stable security invoker set search_path = '' as $$
  select * from private.customer_portal_work_orders();
$$;

revoke all on function private.customer_portal_sales_orders(), private.customer_portal_sales_order_lines(), private.customer_portal_work_orders() from public, anon;
revoke all on function public.customer_portal_sales_orders(), public.customer_portal_sales_order_lines(), public.customer_portal_work_orders() from public, anon;
grant execute on function private.customer_portal_sales_orders(), private.customer_portal_sales_order_lines(), private.customer_portal_work_orders() to authenticated;
grant execute on function public.customer_portal_sales_orders(), public.customer_portal_sales_order_lines(), public.customer_portal_work_orders() to authenticated;

create or replace function private.sync_customer_stage_mapping()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.customer_stage_mappings(routing_step_id, work_order_id, sequence_number, customer_stage_name)
  values (new.id, new.work_order_id, new.sequence_number, new.customer_stage_name)
  on conflict (routing_step_id) do update set work_order_id = excluded.work_order_id, sequence_number = excluded.sequence_number, customer_stage_name = excluded.customer_stage_name;
  return new;
end;
$$;
create trigger routing_step_customer_mapping after insert or update of work_order_id, sequence_number, customer_stage_name on public.routing_steps for each row execute function private.sync_customer_stage_mapping();

create or replace function private.validate_production_event()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  v_work_order public.work_orders%rowtype;
  v_step public.routing_steps%rowtype;
  v_available integer;
  v_original public.production_events%rowtype;
begin
  perform pg_advisory_xact_lock(hashtextextended(new.work_order_id::text, 0));
  select * into strict v_work_order from public.work_orders where id = new.work_order_id;
  select * into strict v_step from public.routing_steps where id = new.routing_step_id and work_order_id = new.work_order_id;
  new.organization_id := v_work_order.organization_id;

  if new.event_type = 'reversal' then
    select * into strict v_original from public.production_events where id = new.reversed_event_id and work_order_id = new.work_order_id and event_type in ('transfer', 'scrap');
    if exists (select 1 from public.production_events where reversed_event_id = v_original.id) then raise exception 'Event has already been reversed'; end if;
    if v_original.created_at < now() - interval '5 minutes' then raise exception 'The undo window for this transaction has expired'; end if;
    new.quantity := v_original.quantity;
    new.routing_step_id := v_original.routing_step_id;
    new.from_routing_step_id := v_original.from_routing_step_id;
    new.to_routing_step_id := v_original.to_routing_step_id;
    return new;
  end if;

  if new.event_type in ('release', 'adjustment') and exists (
    select 1 from public.routing_steps where work_order_id = new.work_order_id and sequence_number < v_step.sequence_number
  ) then raise exception 'Release and adjustment events belong to the first routing step'; end if;

  if new.event_type in ('transfer', 'scrap') then
    select coalesce(sum(delta), 0)::integer into v_available from (
      select case
        when pe.event_type in ('release', 'adjustment') and pe.routing_step_id = new.routing_step_id then pe.quantity
        when pe.event_type = 'transfer' and pe.to_routing_step_id = new.routing_step_id then pe.quantity
        when pe.event_type = 'transfer' and pe.from_routing_step_id = new.routing_step_id then -pe.quantity
        when pe.event_type = 'scrap' and pe.routing_step_id = new.routing_step_id then -pe.quantity
        else 0 end as delta
      from public.production_events pe
      where pe.work_order_id = new.work_order_id and pe.event_type <> 'reversal'
        and not exists (select 1 from public.production_events reversal where reversal.reversed_event_id = pe.id)
    ) balances;
    if new.quantity > v_available then raise exception 'Only % units are available at this routing step', v_available; end if;
  end if;

  if new.event_type = 'transfer' and new.to_routing_step_id is not null and not exists (
    select 1
    from public.routing_steps next_step
    where next_step.id = new.to_routing_step_id
      and next_step.work_order_id = new.work_order_id
      and next_step.sequence_number = (
        select min(candidate.sequence_number)
        from public.routing_steps candidate
        where candidate.work_order_id = new.work_order_id and candidate.sequence_number > v_step.sequence_number
      )
  ) then raise exception 'Transfer destination must be the next routing step on the same work order'; end if;
  if new.event_type = 'transfer' and new.to_routing_step_id is null and exists (
    select 1 from public.routing_steps later_step
    where later_step.work_order_id = new.work_order_id and later_step.sequence_number > v_step.sequence_number
  ) then raise exception 'Only the final routing step can transfer to complete'; end if;
  return new;
end;
$$;
create trigger production_event_validation before insert on public.production_events for each row execute function private.validate_production_event();

create or replace function private.refresh_work_order_completion()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_released integer; v_final_good integer; v_scrap integer; v_ordered integer;
begin
  select quantity_ordered into strict v_ordered from public.work_orders where id = new.work_order_id;
  select
    coalesce(sum(pe.quantity) filter (where pe.event_type in ('release', 'adjustment')), 0)::integer,
    coalesce(sum(pe.quantity) filter (where pe.event_type = 'transfer' and pe.to_routing_step_id is null), 0)::integer,
    coalesce(sum(pe.quantity) filter (where pe.event_type = 'scrap'), 0)::integer
  into v_released, v_final_good, v_scrap
  from public.production_events pe
  where pe.work_order_id = new.work_order_id and pe.event_type <> 'reversal'
    and not exists (select 1 from public.production_events reversal where reversal.reversed_event_id = pe.id);
  update public.work_orders
  set completion_date = case
    when v_released > 0 and v_released - v_final_good - v_scrap = 0 and v_final_good >= v_ordered
      then coalesce(completion_date, new.created_at::date)
    else null
  end
  where id = new.work_order_id;
  return new;
end;
$$;
create trigger production_event_completion after insert on public.production_events for each row execute function private.refresh_work_order_completion();

-- Security-invoker RPCs retain RLS and grants; trigger validation is the single quantity rule.
create or replace function public.record_production_event(
  p_work_order_id uuid, p_routing_step_id uuid, p_event_type text, p_quantity integer, p_to_routing_step_id uuid default null
) returns public.production_events language plpgsql security invoker set search_path = '' as $$
declare v_event public.production_events;
begin
  if p_event_type not in ('transfer', 'scrap', 'adjustment') then raise exception 'Unsupported production event type'; end if;
  insert into public.production_events(organization_id, work_order_id, routing_step_id, event_type, quantity, from_routing_step_id, to_routing_step_id)
  values ('00000000-0000-0000-0000-000000000000', p_work_order_id, p_routing_step_id, p_event_type, p_quantity,
    case when p_event_type = 'transfer' then p_routing_step_id else null end,
    case when p_event_type = 'transfer' then p_to_routing_step_id when p_event_type = 'adjustment' then p_routing_step_id else null end)
  returning * into v_event;
  return v_event;
end;
$$;

create or replace function public.reverse_production_event(p_event_id uuid)
returns void language plpgsql security invoker set search_path = '' as $$
declare v_original public.production_events;
begin
  select * into strict v_original from public.production_events where id = p_event_id;
  insert into public.production_events(organization_id, work_order_id, routing_step_id, event_type, quantity, reversed_event_id)
  values (v_original.organization_id, v_original.work_order_id, v_original.routing_step_id, 'reversal', v_original.quantity, v_original.id);
end;
$$;

create or replace function public.create_sales_order(p_order jsonb, p_lines jsonb)
returns uuid language plpgsql security invoker set search_path = '' as $$
declare v_order_id uuid; v_line jsonb;
begin
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then raise exception 'At least one sales-order line is required'; end if;
  insert into public.sales_orders(organization_id, sales_order_number, customer_id, customer_name, customer_address, customer_po_number, ship_to_address, bill_to_address, date_received, order_due_date, notes)
  values ((p_order->>'organization_id')::uuid, p_order->>'sales_order_number', (p_order->>'customer_id')::uuid, p_order->>'customer_name', coalesce(p_order->>'customer_address', ''), p_order->>'customer_po_number', coalesce(p_order->>'ship_to_address', ''), coalesce(p_order->>'bill_to_address', ''), (p_order->>'date_received')::date, (p_order->>'order_due_date')::date, coalesce(p_order->>'notes', ''))
  returning id into v_order_id;
  for v_line in select value from jsonb_array_elements(p_lines) loop
    insert into public.sales_order_line_items(sales_order_id, line_number, part_number, description, manufactured_item, pricing_type, quantity, unit_price, flat_rate_amount, sort_order)
    values (v_order_id, (v_line->>'line_number')::integer, nullif(v_line->>'part_number', ''), v_line->>'description', (v_line->>'manufactured_item')::boolean, v_line->>'pricing_type', (v_line->>'quantity')::integer, nullif(v_line->>'unit_price', '')::numeric, nullif(v_line->>'flat_rate_amount', '')::numeric, (v_line->>'sort_order')::integer);
  end loop;
  return v_order_id;
end;
$$;

create or replace function public.create_work_order(p_work_order jsonb, p_routing jsonb)
returns uuid language plpgsql security invoker set search_path = '' as $$
declare v_work_order_id uuid; v_step jsonb; v_step_id uuid; v_first_step_id uuid;
begin
  if jsonb_typeof(p_routing) <> 'array' or jsonb_array_length(p_routing) = 0 then raise exception 'At least one routing step is required'; end if;
  if not exists (
    select 1 from public.sales_order_line_items li
    where li.id = (p_work_order->>'sales_order_line_item_id')::uuid and li.sales_order_id = (p_work_order->>'sales_order_id')::uuid and li.manufactured_item
  ) then raise exception 'Work orders must be created from a manufactured sales-order line'; end if;
  insert into public.work_orders(organization_id, work_order_number, sales_order_id, sales_order_line_item_id, part_number, quantity_ordered, due_date, notes)
  values ((p_work_order->>'organization_id')::uuid, p_work_order->>'work_order_number', (p_work_order->>'sales_order_id')::uuid, (p_work_order->>'sales_order_line_item_id')::uuid, p_work_order->>'part_number', (p_work_order->>'quantity_ordered')::integer, (p_work_order->>'due_date')::date, coalesce(p_work_order->>'notes', ''))
  returning id into v_work_order_id;
  for v_step in select value from jsonb_array_elements(p_routing) order by (value->>'sequence_number')::integer loop
    insert into public.routing_steps(work_order_id, sequence_number, routing_step_name, customer_stage_name, work_instructions, work_instructions_revision)
    values (v_work_order_id, (v_step->>'sequence_number')::integer, v_step->>'routing_step_name', coalesce(v_step->>'customer_stage_name', 'In production'), coalesce(v_step->>'work_instructions', ''), nullif(v_step->>'work_instructions_revision', ''))
    returning id into v_step_id;
    if v_first_step_id is null then v_first_step_id := v_step_id; end if;
  end loop;
  insert into public.production_events(organization_id, work_order_id, routing_step_id, event_type, quantity, to_routing_step_id)
  values ((p_work_order->>'organization_id')::uuid, v_work_order_id, v_first_step_id, 'release', (p_work_order->>'quantity_ordered')::integer, v_first_step_id);
  return v_work_order_id;
end;
$$;

revoke all on function public.record_production_event(uuid, uuid, text, integer, uuid) from public, anon;
revoke all on function public.reverse_production_event(uuid) from public, anon;
revoke all on function public.create_sales_order(jsonb, jsonb), public.create_work_order(jsonb, jsonb) from public, anon;
grant execute on function public.record_production_event(uuid, uuid, text, integer, uuid), public.reverse_production_event(uuid), public.create_sales_order(jsonb, jsonb), public.create_work_order(jsonb, jsonb) to authenticated;

-- RLS is enabled on every exposed table. Policies are operation-specific.
alter table public.organizations enable row level security;
alter table public.customers enable row level security;
alter table public.profiles enable row level security;
alter table public.sales_orders enable row level security;
alter table public.sales_order_line_items enable row level security;
alter table public.work_orders enable row level security;
alter table public.routing_steps enable row level security;
alter table public.customer_stage_mappings enable row level security;
alter table public.production_events enable row level security;
alter table public.customer_messages enable row level security;
alter table public.invoices enable row level security;

revoke all on all tables in schema public from anon, authenticated;
grant select on public.organizations, public.customers, public.profiles, public.sales_orders, public.sales_order_line_items, public.work_orders, public.routing_steps, public.customer_stage_mappings, public.production_events, public.customer_messages, public.invoices to authenticated;
grant insert, update on public.customers, public.sales_orders, public.sales_order_line_items, public.routing_steps to authenticated;
grant insert on public.work_orders to authenticated;
grant update(due_date, notes) on public.work_orders to authenticated;
grant insert on public.production_events, public.customer_messages, public.invoices to authenticated;
grant update(read_at) on public.customer_messages to authenticated;

create policy organizations_select on public.organizations for select to authenticated using (exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.organization_id = organizations.id));
create policy profiles_select on public.profiles for select to authenticated using (id = (select auth.uid()) or (select private.is_manufacturer(organization_id)));

create policy customers_select on public.customers for select to authenticated using ((select private.can_access_customer(organization_id, id)));
create policy customers_insert on public.customers for insert to authenticated with check ((select private.is_manufacturer(organization_id)));
create policy customers_update on public.customers for update to authenticated using ((select private.is_manufacturer(organization_id))) with check ((select private.is_manufacturer(organization_id)));

create policy sales_orders_select on public.sales_orders for select to authenticated using ((select private.is_manufacturer(organization_id)));
create policy sales_orders_insert on public.sales_orders for insert to authenticated with check ((select private.is_manufacturer(organization_id)));
create policy sales_orders_update on public.sales_orders for update to authenticated using ((select private.is_manufacturer(organization_id))) with check ((select private.is_manufacturer(organization_id)));

create policy line_items_select on public.sales_order_line_items for select to authenticated using (exists (select 1 from public.sales_orders so where so.id = sales_order_id and (select private.is_manufacturer(so.organization_id))));
create policy line_items_insert on public.sales_order_line_items for insert to authenticated with check (exists (select 1 from public.sales_orders so where so.id = sales_order_id and (select private.is_manufacturer(so.organization_id))));
create policy line_items_update on public.sales_order_line_items for update to authenticated using (exists (select 1 from public.sales_orders so where so.id = sales_order_id and (select private.is_manufacturer(so.organization_id)))) with check (exists (select 1 from public.sales_orders so where so.id = sales_order_id and (select private.is_manufacturer(so.organization_id))));

create policy work_orders_select on public.work_orders for select to authenticated using ((select private.is_manufacturer(organization_id)));
create policy work_orders_insert on public.work_orders for insert to authenticated with check ((select private.is_manufacturer(organization_id)));
create policy work_orders_update on public.work_orders for update to authenticated using ((select private.is_manufacturer(organization_id))) with check ((select private.is_manufacturer(organization_id)));

create policy routing_steps_select on public.routing_steps for select to authenticated using (exists (select 1 from public.work_orders wo where wo.id = work_order_id and (select private.is_manufacturer(wo.organization_id))));
create policy routing_steps_insert on public.routing_steps for insert to authenticated with check (exists (select 1 from public.work_orders wo where wo.id = work_order_id and (select private.is_manufacturer(wo.organization_id))));
create policy routing_steps_update on public.routing_steps for update to authenticated using (exists (select 1 from public.work_orders wo where wo.id = work_order_id and (select private.is_manufacturer(wo.organization_id)))) with check (exists (select 1 from public.work_orders wo where wo.id = work_order_id and (select private.is_manufacturer(wo.organization_id))));

create policy customer_stage_mappings_select on public.customer_stage_mappings for select to authenticated using (exists (select 1 from public.work_orders wo where wo.id = work_order_id and (select private.is_manufacturer(wo.organization_id))));
create policy production_events_select on public.production_events for select to authenticated using ((select private.is_manufacturer(organization_id)));
create policy production_events_insert on public.production_events for insert to authenticated with check ((select private.is_manufacturer(organization_id)));

create policy customer_messages_select on public.customer_messages for select to authenticated using ((select private.can_access_customer(organization_id, customer_id)));
create policy customer_messages_insert on public.customer_messages for insert to authenticated with check ((select private.can_access_customer(organization_id, customer_id)) and sender_type = (select role from public.profiles where id = (select auth.uid())));
create policy customer_messages_update on public.customer_messages for update to authenticated using ((select private.can_access_customer(organization_id, customer_id))) with check ((select private.can_access_customer(organization_id, customer_id)));

create policy invoices_select on public.invoices for select to authenticated using ((select private.can_access_customer(organization_id, customer_id)));
create policy invoices_insert on public.invoices for insert to authenticated with check ((select private.is_manufacturer(organization_id)));

-- Private PDF bucket and object policies. Object paths are org/customer/random-file.pdf.
insert into storage.buckets(id, name, public, file_size_limit, allowed_mime_types)
values ('invoices', 'invoices', false, 10485760, array['application/pdf'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

create policy invoice_objects_select on storage.objects for select to authenticated using (
  bucket_id = 'invoices' and exists (
    select 1 from public.invoices i where i.file_path = name and (select private.can_access_customer(i.organization_id, i.customer_id))
  )
);
create policy invoice_objects_insert on storage.objects for insert to authenticated with check (
  bucket_id = 'invoices'
  and lower(storage.extension(name)) = 'pdf'
  and coalesce(metadata->>'mimetype', '') = 'application/pdf'
  and (select private.is_manufacturer(((storage.foldername(name))[1])::uuid))
);
create policy invoice_objects_delete on storage.objects for delete to authenticated using (
  bucket_id = 'invoices' and (select private.is_manufacturer(((storage.foldername(name))[1])::uuid))
);
